def _safe_has_all(self, member) -> bool:
    """Safely check if a member has __all__ attribute.

    Some C extension modules may raise exceptions when accessing attributes,
    for example PyQt5.QtWidgets.qApp which raises RuntimeError if QApplication
    is not initialized. This method safely handles such cases.
    """
    try:
        return hasattr(member, "__all__")
    except Exception:  # pylint: disable=broad-except
        return False

